import sys

def is_good_subsequence(substring, s):
    n = len(s)
    m = len(substring)

    # Check all possible subsequences of s
    for i in range(n):
        for j in range(i + 1, n):
            if s[i] == substring[0] and s[j] == substring[-1]:
                # Check if there is at least one character between i and j
                if any(s[k] == substring[1] for k in range(i + 1, j)):
                    return True
    return False

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1

    results = []

    for _ in range(t):
        n = int(data[index])
        q = int(data[index + 1])
        index += 2

        s = data[index]
        index += 1

        queries = []
        for _ in range(q):
            l_i = int(data[index]) - 1
            r_i = int(data[index + 1])
            index += 2
            queries.append((l_i, r_i))

        for l_i, r_i in queries:
            substring = s[l_i:r_i]
            if is_good_subsequence(substring, s):
                results.append("YES")
            else:
                results.append("NO")

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
